/bin/bash -lc "python - <<'PY'
import mujoco
from sim import Sim
sim=Sim()
print('sites:')
for i in range(sim.model.nsite):
    print(i, mujoco.mj_id2name(sim.model, mujoco.mjtObj.mjOBJ_SITE, i))
print('bodies with names:')
for i in range(sim.model.nbody):
    n = mujoco.mj_id2name(sim.model, mujoco.mjtObj.mjOBJ_BODY, i)
    if n:
        print(i,n)
print('geoms with names:')
for i in range(sim.model.ngeom):
    n = mujoco.mj_id2name(sim.model, mujoco.mjtObj.mjOBJ_GEOM, i)
    if n:
        if any(k in n for k in ['hand','finger','palm','grip','link','cup','wall','table','floor','cup']):
            print(i,n)
print('geom body map for selected geoms:')
for i in [g for g in range(sim.model.ngeom) if mujoco.mj_id2name(sim.model, mujoco.mjtObj.mjOBJ_GEOM, g)]:
    gname = mujoco.mj_id2name(sim.model, mujoco.mjtObj.mjOBJ_GEOM, i)
    if any(k in gname for k in ['hand','finger','link7','link6','cup','wall','table','hand_c']):
      print(i,gname,'bodyid',int(sim.model.geom_bodyid[i]), 'body',mujoco.mj_id2name(sim.model,mujoco.mjtObj.mjOBJ_BODY,int(sim.model.geom_bodyid[i])))
PY"

